export type Theme = keyof typeof tokens.color;
export type ColorRole = keyof typeof tokens.color.dark;
export type SemanticColor = keyof typeof tokens.extendedColor.dark.semantic;
export type ToolCategory = keyof typeof tokens.extendedColor.dark.tool;
export type TypeRole = keyof typeof tokens.typography.scale;
export type ShapeKey = keyof typeof tokens.shape;
export type SpaceKey = keyof typeof tokens.spacing;

export const toolCategories = ["read","write","execute","script","navigate","capture","interact","todo","task","system","agent","search"] as const;

const kebab = (s: string): string => s.replace(/([a-z0-9])([A-Z])/g, "$1-$2").toLowerCase();

/** CSS custom-property references matching dist/tokens.css. */
export const cssVar = {
  color: (role: ColorRole): string => `var(--md-sys-color-${kebab(role)})`,
  tool: (c: ToolCategory, v: "" | "on" | "container" | "on-container" | "tint" = ""): string =>
    v === "on" ? `var(--md-ext-color-on-tool-${c})`
    : v === "on-container" ? `var(--md-ext-color-on-tool-${c}-container)`
    : v ? `var(--md-ext-color-tool-${c}-${v})` : `var(--md-ext-color-tool-${c})`,
  type: (role: TypeRole | "code", prop: "font" | "size" | "line-height" | "weight" | "tracking"): string =>
    `var(--md-sys-typescale-${kebab(role)}-${prop})`,
  shape: (k: ShapeKey): string => `var(--md-sys-shape-corner-${kebab(k)})`,
  space: (k: SpaceKey): string => `var(--app-space-${k})`,
} as const;
